 id='rou_2025_'+s;u='https://ssmr.ro/files/onm2025/faza_nationala/%02d_solutii_bareme_ONM_2025.pdf'%g
 r[id]={'difficulty':d,'topic':t,'tags':tags,'reason':reason,'sourceUrl':u,'solutionUrl':u+'#page='+str(page),'sourceName':'Romanian Mathematical Society — official 2025 national solutions','solutionKind':'source-link','solution':'[Official worked solution]('+u+'#page='+str(page)+').'}
