add('847f79',7,5,'Geometry',['similar triangles','angle bisectors'], 'Similarity proves the parallelism; identifying the common angle bisector proves collinearity.',r'In right triangle $ABC$ with $\angle A=90^\circ$, let $AD\perp BC$. Choose $E,H$ on ray $AD$ with $AE=AC$, $AH=AB$. Construct squares $AEFG,AHJI$ containing $C,B$, respectively. Set $K=AC\cap EG$, $L=AB\cap IH$, $N=IL\cap GK$, $M=IB\cap GC$. Prove $KL\parallel BC$ and that $A,N,M$ are collinear.',2)
