add('final8_2',8,4.5,'Algebra',['fractional parts','rationality'],'Ordering forces two variables equal; a rational discriminant restricts the remaining ratio.',r'Positive reals $a,b,c$ satisfy $\{a/(b+c)\}=\{b/(c+a)\}=\{c/(a+b)\}$. Prove that two are equal, and that all three are equal if they are rational.')
add('27137e',8,4,'Algebra',['rational roots','elimination'],'Eliminate the irrational term in each case, then use the rational-root theorem.',r'If $a\in\mathbb R$, $a+a^2+a^3\in\mathbb Z$, and at least one of $a,a^2,a^3$ is rational, prove $a\in\mathbb Z$.')
