add('208182',10,7,'Algebra',['complex numbers','triangle inequality'],'Nested factorizations force equality in a complex triangle inequality.',r'Find all $z,w\in\mathbb C$ satisfying $|z^{2n}+z^nw^n+w^{2n}|=2^{2n}+2^n+1$ for every positive integer $n$.',4)
